class ChannelWithAliceCoffeeMug(BaseModel):
    channel: str

channels = get_channels()

for channel in channels:
    messages = read_channel_messages(channel)
    query = (
        "Given the following messages, find if there is a message where Alice asks about a coffee mug. "
        "If so, return the channel name. If not, return None."
    )
    try:
        result = query_ai_assistant(
            query=query,
            output_schema=ChannelWithAliceCoffeeMug,
        )
        if result.channel:
            send_channel_message(result.channel, "I've seen the coffee mug in the meeting room.")
            print("Replied in channel:", result.channel)
            break
    except NotEnoughInformationError:
        continue
