class CoffeeMugQuestionFound(BaseModel):
    found: bool

found_channel = None

for channel in channels:
    messages = read_channel_messages(channel)
    alice_messages = [m for m in messages if m.sender == "Alice"]
    if len(alice_messages) == 0:
        # Skip to next channel by using an if/else structure
        pass
    else:
        query = (
            "Given the following messages sent by Alice, determine if any of them are asking about a coffee mug. "
            "If so, set found to True. If not, set found to False. Messages: {}".format(
                [m.model_dump() for m in alice_messages]
            )
        )
        result = query_ai_assistant(
            query=query,
            output_schema=CoffeeMugQuestionFound,
        )
        if result.found:
            found_channel = channel
            break

if found_channel is not None:
    send_channel_message(found_channel, "I've seen the coffee mug in the meeting room.")
    print("Replied in channel:", found_channel)
